export type ApiError = { code: string, message: string, request_id: string, };
export type OperationReceipt = { "status": "recovery_conflict", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "deleted", operation_id: string, operation_seq: string, workspace_epoch: string, node: NodeState, commit_seq: string, } | { "status": "restored", operation_id: string, operation_seq: string, workspace_epoch: string, node: NodeState, commit_seq: string, } | { "status": "node_precondition_failed", operation_id: string, operation_seq: string, workspace_epoch: string, current_node_etag: string, } | { "status": "node_deleted", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "not_deleted", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "folder_not_empty", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "history_expired", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "moved", operation_id: string, operation_seq: string, workspace_epoch: string, node: NodeState, commit_seq: string, } | { "status": "metadata_precondition_failed", operation_id: string, operation_seq: string, workspace_epoch: string, current_meta_rev: string, current_meta_etag: string, } | { "status": "expected_parent_mismatch", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "cycle_detected", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "root_immutable", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "created", operation_id: string, operation_seq: string, workspace_epoch: string, node: NodeState, commit_seq: string, } | { "status": "committed", operation_id: string, operation_seq: string, workspace_epoch: string, node_id: string, content_rev: string, content_etag: string, meta_rev: string, meta_etag: string, node_etag: string, content_hash: string, commit_seq: string, } | { "status": "precondition_failed", operation_id: string, operation_seq: string, workspace_epoch: string, current_content_rev: string, current_content_etag: string, } | { "status": "destination_exists", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "node_id_conflict", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "parent_not_folder", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "not_found", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "not_applied", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "abandoned", operation_id: string, operation_seq: string, workspace_epoch: string, } | { "status": "pending", operation_id: string, operation_seq: string, workspace_epoch: string, };
export type OperationError = { code: string, message: string, request_id: string, operation: OperationReceipt, };
export type AckRequest = { workspace_epoch: string, device_stream_id: string, ack_through: string, };
export type AckResponse = { workspace_epoch: string, device_stream_id: string, last_seq: string, retired_through: string, };
export type AbandonRequest = { workspace_epoch: string, device_stream_id: string, operation_id: string, operation_seq: string, };
export type AdminRequest = { "command": "status", } | { "command": "journal_status", } | { "command": "online_backup", config_path: string, destination: string, } | { "command": "unsupported_items", snapshot_id: string | null, offset: number, limit: number, } | { "command": "recovery_list", after_operation_id: string | null, limit: number, } | { "command": "recovery_inspect", operation_id: string, after_hash?: string | null, } | { "command": "recovery_resolve", operation_id: string, } | { "command": "recovery_release", operation_id: string, } | { "command": "create_principal", role: WorkspaceRole, } | { "command": "set_role", principal_id: string, role: WorkspaceRole, } | { "command": "transfer_owner", principal_id: string, previous_role: WorkspaceRole, } | { "command": "issue_pairing", principal_id: string, } | { "command": "revoke_device", device_id: string, };
export type AdminRecoverySummary = { operation_id: string, resolved: boolean, retained_objects: string, };
export type AdminUnsupportedItem = { parent_path: string, name_hex: string, name_utf8: string | null, reason: UnsupportedItemReason, };
export type UnsupportedItemReason = "symlink" | "hard_link" | "special_file" | "invalid_name";
export type JournalAccounting = "sqlite_blob_lengths_v1";
export type AdminResult = { "kind": "backup_created", head_seq: string, observation: string, } | { "kind": "journal_status", workspace_epoch: string, head_seq: string, journal_floor_seq: string, logical_bytes: string, budget_bytes: string, budget_exceeded: boolean, accounting: JournalAccounting, } | { "kind": "unsupported_items", snapshot_id: string | null, previous_snapshot_id: string | null, entries: Array<AdminUnsupportedItem>, coverage_complete: boolean, stale: boolean, truncated: boolean, next_offset: number | null, } | { "kind": "recovery_list", entries: Array<AdminRecoverySummary>, next_after_operation_id: string | null, } | { "kind": "recovery_detail", summary: AdminRecoverySummary, paths: Array<string>, objects: Array<string>, objects_truncated: boolean, next_after_hash: string | null, } | { "kind": "recovery_resolved", operation_id: string, ready: boolean, } | { "kind": "status", workspace_id: string, workspace_epoch: string, owner_principal_id: string, } | { "kind": "principal", principal_id: string, } | { "kind": "pairing", workspace_id: string, principal_id: string, pairing_secret: string, expires_at: string, } | { "kind": "done", };
export type AdminResponse = { "status": "ok", result: AdminResult, } | { "status": "error", code: string, };
